package io.github.wizard302.wise4chess.core.chess

/** Zobrist keys for position hashing, generated by SplitMix64 from a fixed seed. */
internal object Zobrist {
    /** Indexed by `(side.ordinal * 6 + type.ordinal) * 64 + square`. */
    val PIECE = LongArray(12 * 64)
    val CASTLING_ROOK = LongArray(64)
    val EN_PASSANT_FILE = LongArray(8)
    val BLACK_TO_MOVE: Long

    init {
        var state = 0x57495345_34434845L // "WISE4CHE"
        fun next(): Long {
            state += -0x61c8864680b583ebL // 0x9E3779B97F4A7C15
            var z = state
            z = (z xor (z ushr 30)) * -0x40a7b892e31b1a47L // 0xBF58476D1CE4E5B9
            z = (z xor (z ushr 27)) * -0x6b2fb644ecceee15L // 0x94D049BB133111EB
            return z xor (z ushr 31)
        }
        for (i in PIECE.indices) PIECE[i] = next()
        for (i in CASTLING_ROOK.indices) CASTLING_ROOK[i] = next()
        for (i in EN_PASSANT_FILE.indices) EN_PASSANT_FILE[i] = next()
        BLACK_TO_MOVE = next()
    }
}
